function sNullT() {
  return CW('kt-null-checks', {
    code: ['fun len(a: String, b: String, c: String)', '  = a.length + b.length + c.length', '// bytecode: checkNotNullParameter x 3', 'Greeter.len(null)   // called from Java', 'kotlinc -Xno-param-assertions'],
    hl: [[0, 3, 'accent'], [3, 1, 'danger'], [4, 1, 'warn'], null],
    draw: (S) => {
      rbars(S, 'b1', .5, [['String x3', 2.8, 'accent', '1.76 ns'], ['no assert', 2.6, 'ok', '1.64 ns'], ['String? x3', 4.2, 'warn', '2.57–2.63']], 1);
      lbl(S, 'l1', 19.0, 2.3, ['public 함수는 매개변수마다 null 검사를 한 번씩 넣어요', 'public functions check each parameter once'], 'a', 1, { w: 12.4 });
      mono(S, 'm2', 19.0, 3.6, nbs(['Parameter specified as non-null', 'is null: ... Greeter.len, parameter a']), 2, { w: 12.4, dy: .55, c: 'kox-r' });
      lbl(S, 'l2', 19.0, 4.9, ['Java가 null을 넘기자 함수 입구에서 어느 매개변수인지 알려 줬어요', 'when Java passed null, it failed at the entry and named the parameter'], 'r', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 6.3, ['검사를 끄면 0개, 1.76ns가 1.64ns가 돼요', 'turning them off leaves 0 checks: 1.76 ns becomes 1.64 ns'], 'w', 3, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['null 검사는 Java와 만나는 경계를 지키는 비용이에요', 'null checks are the cost of guarding the boundary with Java'], 'a', 4, { w: 16.0 });
    },
    notes: [['Kotlin 타입 String은 null이 될 수 없지만, Java 코드는 그 약속을 몰라요 · 그래서 kotlinc는 public 함수 입구에 매개변수마다 Intrinsics.checkNotNullParameter를 넣어요 · 매개변수 3개짜리 함수에서 3번 호출됐어요', 'the Kotlin type String cannot be null, but Java code does not know that promise, so kotlinc puts Intrinsics.checkNotNullParameter at the entry of a public function for every parameter, three calls for a function with three parameters'], ['Java에서 null을 넘기자 함수 본문이 시작되기 전에 "Parameter specified as non-null is null: method s1.Greeter.len, parameter a"로 멈췄어요 · 반대로 !!는 메시지 없는 NullPointerException이었어요', 'passing null from Java stopped before the body started with "Parameter specified as non-null is null: method s1.Greeter.len, parameter a", whereas !! threw a NullPointerException with no message'], ['-Xno-param-assertions로 검사를 빼면 0번이 돼요 · 2,000만 번 호출에서 1.76ns가 1.64ns가 됐어요 · String?를 받아 직접 처리한 판은 2.57~2.63ns였어요', 'with -Xno-param-assertions the checks drop to zero, and over 20 million calls 1.76 ns became 1.64 ns, while a version taking String? and handling null itself took 2.57 to 2.63 ns'], ['호출당 약 0.1ns로 잘못된 null이 들어온 자리를 바로 알려 줘요 · 검사를 끄면 null이 안쪽 깊은 곳까지 흘러가요 · 대부분의 코드는 그대로 두는 편이 나아요', 'for about 0.1 ns per call it pinpoints where a bad null entered, and turning it off lets the null travel deep inside, so most code is better off leaving it on']],
    fin: [['null 검사는 경계에', 'null checks sit at the boundary', 'kox-xs kox-a'], ['호출당 약 0.1ns', 'about 0.1 ns per call'], ['어느 매개변수인지 알려 줘요', 'it names the parameter']],
    caps: [['매개변수마다 검사', 'A check per parameter'], ['Java가 넘긴 null', 'A null from Java'], ['검사 끄기', 'Turning checks off'], ['경계를 지키는 비용', 'The cost of the boundary'], ['null 검사', 'Null checks']]
  });
}

