    hl: [[3, 2, 'accent'], [0, 2, 'danger'], [2, 1, 'ok'], null],
    draw: (S) => {
      mono(S, 'm0', 19.0, .5, nbs(['             C2 JIT     C1 only', 'no capture   0.27 ns', 'capture      0.74 ns    44.27 ns  64 B', 'inline       0.45 ns     0.83 ns   0 B']), 1, { w: 12.4, dy: .55 });
      lbl(S, 'l1', 19.0, 2.9, ['JIT이 다 데운 뒤에는 값을 잡는 람다도 0.74ns, 할당 0B였어요', 'fully warmed by the JIT, even a capturing lambda took 0.74 ns with 0 B'], 'g', 1, { w: 12.4 });
      lbl(S, 'l2', 19.0, 4.3, ['C1까지만 컴파일하자 inline이 아닌 호출은 44.27ns, 호출마다 64B였어요', 'compiled only up to C1, the non-inline call took 44.27 ns and 64 B per call'], 'r', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 5.7, ['inline 판은 C1에서도 0.83ns, 0B였어요', 'the inline version took 0.83 ns and 0 B even under C1'], 'a', 3, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['inline은 JIT이 할 일을 컴파일러가 미리 해 두는 거예요', 'inline does ahead of time what the JIT would otherwise have to do'], 'a', 4, { w: 16.0 });
    },
    notes: [['함수를 인자로 받는 고차 함수는 호출할 때마다 람다 객체를 넘겨요 · 람다가 바깥 값 k를 잡으면 그 값을 담은 객체가 필요해요 · applyTwice를 2,000만 번 부르며 inline 유무를 비교했어요', 'a higher-order function receives a lambda object on every call, and a lambda capturing an outside value k needs an object holding it, so applyTwice was called 20 million times with and without inline'], ['JIT이 다 데운 C2 상태에서는 잡는 값이 없는 람다 0.27ns, k를 잡는 람다 0.74ns, inline 0.45ns였어요 · 셋 다 할당이 0B였어요 · JIT이 호출을 펼치고 객체를 없앴어요', 'fully warmed under C2, a non-capturing lambda took 0.27 ns, one capturing k 0.74 ns and inline 0.45 ns, all with 0 B, because the JIT inlined the calls and removed the objects'], ['-XX:TieredStopAtLevel=1로 C1 컴파일러까지만 쓰자 차이가 드러났어요 · inline이 아닌 호출은 44.27ns, 호출마다 64B를 만들었어요 · inline은 0.83ns, 0B였어요', 'stopping at the C1 compiler with -XX:TieredStopAtLevel=1 exposed the difference: the non-inline call took 44.27 ns and allocated 64 B per call, inline 0.83 ns and 0 B'], ['Kotlin 2.4는 람다를 invokedynamic으로 만들어 클래스 파일이 따로 생기지 않았어요 · -Xlambdas=class로 옛 방식을 쓰자 람다마다 약 1.2KB 클래스 3개가 더 생겼어요', 'Kotlin 2.4 compiles lambdas with invokedynamic, so no extra class files appeared, while the old scheme via -Xlambdas=class added three classes of about 1.2 KB, one per lambda']],
    fin: [['inline은 호출을 미리 펼쳐요', 'inline expands calls ahead of time', 'kox-xs kox-a'], ['C2에선 차이 작음', 'small gap under C2'], ['C1에선 44ns와 0.8ns', '44 ns versus 0.8 ns under C1']],
