function sScopeT() {
  return CW('kt-scope', {
    code: ['fun withApply() = Person().apply {', '  name = "kim"; age = 30 }        // 26 bytes', 'fun manual(): Person { val p = Person()', '  p.name = "kim"; p.age = 30; return p } // 22', 'p.email?.let { it.length } ?: 0  // 28 vs 25'],
    hl: [[0, 4, 'accent'], [4, 1, 'ok'], null, null],
    draw: (S) => {
      rbars(S, 'b1', .5, [['apply', 2.6, 'accent', '26 bytes'], ['manual', 2.2, 'ink-3', '22 bytes'], ['let', 2.8, 'accent', '28 bytes'], ['if != null', 2.5, 'ink-3', '25 bytes']], 1);
      lbl(S, 'l1', 19.0, 2.9, ['apply와 let은 inline이라 직접 쓴 코드보다 3~4바이트만 컸어요', 'apply and let are inline, only 3 to 4 bytes larger than hand-written code'], 'g', 1, { w: 12.4 });
      lbl(S, 'l2', 19.0, 4.3, ['invokedynamic도 람다 메서드도 없이 호출한 자리에 펼쳐졌어요', 'no invokedynamic and no lambda method: they were expanded in place'], 'a', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 5.7, ['run, let, also, let을 겹친 한 줄은 96바이트, 명령 52개가 됐어요', 'one line nesting run, let, also and let became 96 bytes, 52 instructions'], 'w', 3, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['범위 함수는 속도가 아니라 읽기 쉬움으로 골라요', 'choose scope functions for readability, not speed'], 'a', 4, { w: 16.0 });
    },
    notes: [['apply, let, run, also, with는 객체를 잠깐 this나 it으로 부르게 해 주는 범위 함수예요 · 모두 inline 함수예요 · 같은 일을 범위 함수와 직접 쓴 코드로 만들어 바이트코드를 비교했어요', 'apply, let, run, also and with are scope functions that briefly let an object be called this or it, all of them inline, so the same work was written with scope functions and by hand and the bytecode compared'], ['Person을 만들고 두 필드를 채우는 코드는 apply 판 26바이트, 직접 쓴 판 22바이트였어요 · null이면 0을 돌려주는 let 판은 28바이트, if 판은 25바이트였어요 · 차이는 임시 지역 변수 몇 개였어요', 'creating a Person and setting two fields took 26 bytes with apply and 22 by hand, and returning 0 for null took 28 bytes with let and 25 with if, the difference being a few temporary local variables'], ['어느 판에도 invokedynamic이나 람다 메서드가 없었어요 · 람다 본문이 호출한 함수 안에 그대로 펼쳐졌어요', 'none of them contained invokedynamic or a lambda method, the lambda bodies being expanded straight into the calling function'], ['비용이 거의 없다 보니 겹쳐 쓰기 쉬워요 · p.run { email?.let { e -> name.also { … }.let { … } } }처럼 네 개를 겹친 한 줄이 96바이트, 명령 52개가 됐어요 · 이 정도면 this와 it이 무엇인지 읽기 어려워져요', 'being nearly free makes them easy to nest, and one line nesting four, p.run { email?.let { e -> name.also { … }.let { … } } }, became 96 bytes and 52 instructions, by which point it is hard to tell what this and it refer to']],
    fin: [['범위 함수는 inline', 'scope functions are inline', 'kox-xs kox-a'], ['3~4바이트 차이', '3 to 4 bytes apart'], ['겹치면 읽기 어려워요', 'nesting hurts readability']],
    caps: [['범위 함수 다섯 개', 'Five scope functions'], ['바이트코드 크기', 'Bytecode size'], ['펼쳐진 람다', 'Expanded lambdas'], ['겹쳐 쓰기', 'Nesting them'], ['범위 함수', 'Scope functions']]
  });
}
