function sSuspendT() {
  return CW('kt-suspend', {
    code: ['suspend fun load(id: Int): String {', '  val u = fetchUser(id)       // suspend 1', '  val o = fetchUser(id + 1)   // suspend 2', '  val p = fetchUser(id + 2)   // suspend 3', '  return u + o + p }'],
    hl: [[0, 1, 'warn'], [1, 3, 'accent'], [1, 3, 'ok'], null],
    draw: (S) => {
      mono(S, 'm0', 19.0, .5, nbs(['Object load(int, Continuation)']), 1, { w: 12.4, c: 'kox-w' });
      lbl(S, 'l1', 19.0, 1.15, ['suspend 함수는 Continuation을 하나 더 받고 Object를 돌려줘요', 'a suspend function takes an extra Continuation and returns Object'], 'w', 1, { w: 12.4 });
      mono(S, 'm2', 19.0, 2.6, nbs(['SmKt$load$1 extends ContinuationImpl', '  int I$0;  Object L$0, L$1;', '  Object result;  int label']), 2, { w: 12.4, dy: .55 });
      lbl(S, 'l2', 19.0, 4.4, ['멈췄다 이어 갈 지역 변수를 담는 상태 객체가 생겨요', 'a state object holds the locals needed to resume'], 'a', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 5.8, ['멈추는 지점 3개는 label 0~3을 고르는 tableswitch가 됐어요', 'the three suspension points became a tableswitch over label 0 to 3'], 'g', 3, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['suspend는 스레드를 멈추지 않고 함수를 상태 기계로 나눠요', 'suspend splits a function into a state machine instead of blocking a thread'], 'a', 4, { w: 16.0 });
    },
    notes: [['suspend 함수는 중간에 멈췄다가 나중에 이어 갈 수 있어요 · JVM에는 그런 기능이 없어서 컴파일러가 함수를 바꿔 써요 · fetchUser를 세 번 부르는 load를 javap로 봤어요', 'a suspend function can pause midway and resume later, which the JVM cannot do natively, so the compiler rewrites the function, and javap was used on load, which calls fetchUser three times'], ['load의 시그니처는 Object load(int, Continuation)였어요 · 마지막에 Continuation이 붙고, 반환 타입은 String이 아니라 Object예요 · 멈출 때는 결과 대신 COROUTINE_SUSPENDED 표시를 돌려주기 때문이에요', 'the signature of load was Object load(int, Continuation), with a Continuation appended and Object instead of String as the return type, because when it pauses it returns a COROUTINE_SUSPENDED marker instead of a result'], ['SmKt$load$1이라는 클래스가 따로 생겼어요 · ContinuationImpl을 상속하고 int I$0, Object L$0, L$1, result, int label 필드를 가져요 · 멈춘 사이 살아 있어야 할 id와 u, o를 담아요', 'a separate class, SmKt$load$1, appeared, extending ContinuationImpl with fields int I$0, Object L$0, L$1, result and int label to hold id, u and o, which must survive while paused'], ['본문은 label 0부터 3까지 고르는 tableswitch가 됐어요 · fetchUser가 끝나면 label을 보고 다음 지점부터 이어 가요 · 1번 멈추는 fetchUser는 0부터 1까지였어요', 'the body became a tableswitch over label 0 to 3, resuming from the next point by label when fetchUser completes, while fetchUser, which pauses once, switched over 0 to 1']],
    fin: [['suspend는 상태 기계', 'suspend is a state machine', 'kox-xs kox-a'], ['지역 변수는 객체 필드로', 'locals become object fields'], ['멈춰도 스레드는 놓아요', 'pausing frees the thread']],
    caps: [['멈췄다 이어 가기', 'Pausing and resuming'], ['바뀐 시그니처', 'The changed signature'], ['상태 객체', 'The state object'], ['label과 tableswitch', 'label and tableswitch'], ['suspend 함수', 'Suspend functions']]
  });
}

function sDispT() {
  return CW('kt-dispatchers', {
    code: ['repeat(100) { launch(Dispatchers.Default) {', '  Thread.sleep(100) } }        // 5,032 ms', 'launch(Dispatchers.IO) { Thread.sleep(100) }', 'launch(Dispatchers.Default) { delay(100) }', 'IO.limitedParallelism(10)       // 1,006 ms'],
    hl: [[0, 2, 'danger'], [2, 2, 'ok'], [0, 2, 'danger'], [4, 1, 'warn']],
    draw: (S) => {
      rbars(S, 'b1', .5, [['Default', 5.0, 'danger', '5,032 ms'], ['IO', .21, 'ok', '212 ms'], ['delay', .11, 'ok', '114 ms'], ['limit 10', 1.0, 'warn', '1,006 ms']], 1);
      lbl(S, 'l1', 19.0, 2.9, ['코어 2개에서 Default는 한 번에 2개씩만 돌아, 100ms 잠자는 작업 100개가 5초 걸렸어요', 'with 2 cores Default ran 2 at a time, so 100 tasks sleeping 100 ms took 5 s'], 'r', 1, { w: 12.4 });
      lbl(S, 'l2', 19.0, 4.3, ['IO는 212ms, sleep 대신 delay를 쓰자 Default에서도 114ms였어요', 'IO took 212 ms, and with delay instead of sleep even Default took 114 ms'], 'g', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 5.7, ['Default를 막자 상관없는 작은 작업도 2,001ms를 기다렸어요', 'blocking Default made an unrelated small task wait 2,001 ms'], 'r', 3, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['막는 호출은 IO로, Default는 계산에만 써요', 'blocking calls go to IO; Default is for computation'], 'a', 4, { w: 16.0 });
    },
    notes: [['디스패처는 코루틴을 어느 스레드에서 돌릴지 정해요 · Default는 계산용으로 스레드 수가 코어 수에 맞춰져요 · 코어 2개인 컨테이너에서 100ms 동안 Thread.sleep하는 작업 100개를 돌렸어요', 'a dispatcher decides which threads run a coroutine, and Default, meant for computation, sizes its threads to the core count, so 100 tasks each calling Thread.sleep for 100 ms were run in a 2-core container'], ['Default에서는 5,032ms가 걸렸어요 · sleep은 스레드를 붙잡고 놓지 않아서 한 번에 2개씩만 돌았어요 · IO 디스패처는 스레드를 64개까지 늘려 212ms에 끝냈어요', 'on Default it took 5,032 ms, since sleep holds its thread and only two ran at a time, while the IO dispatcher, which grows to 64 threads, finished in 212 ms'], ['같은 Default에서 sleep 대신 delay를 쓰자 114ms였어요 · delay는 스레드를 놓고 기다려요 · 반대로 Default에서 1초씩 막는 작업 4개를 돌리자 상관없는 작은 작업이 2,001ms 뒤에야 시작했어요', 'on the same Default, delay instead of sleep took 114 ms because delay releases the thread while waiting, whereas four tasks blocking Default for 1 s each delayed an unrelated small task until 2,001 ms'], ['막는 호출을 피할 수 없으면 withContext(Dispatchers.IO)로 옮겨요 · 데이터베이스 연결 수처럼 상한이 있으면 IO.limitedParallelism(10)으로 묶어요 · 이때 100개는 1,006ms였어요', 'unavoidable blocking calls move to withContext(Dispatchers.IO), and where there is a limit such as database connections, IO.limitedParallelism(10) caps them, taking 1,006 ms for the 100 tasks']],
    fin: [['sleep은 스레드를 붙잡아요', 'sleep holds the thread', 'kox-xs kox-a'], ['Default에서 5초', '5 s on Default'], ['막는 일은 IO로', 'blocking work goes to IO']],
    caps: [['디스패처', 'Dispatchers'], ['Default에서 잠자기', 'Sleeping on Default'], ['IO와 delay', 'IO and delay'], ['막힌 Default', 'A blocked Default'], ['디스패처 고르기', 'Choosing a dispatcher']]
  });
}

function sCancelT() {
  return CW('kt-cancel', {
    code: ['val j = launch(Dispatchers.Default) {', '  repeat(20) { spin(100); steps++ } }', 'delay(250); j.cancel(); j.join()', 'repeat(20) { ensureActive(); spin(100) }', 'try { delay(100) } catch (e: Exception) {}'],
    hl: [[0, 3, 'danger'], [3, 1, 'ok'], [4, 1, 'warn'], null],
    draw: (S) => {
      mono(S, 'm0', 19.0, .5, nbs(['                  ends at    steps', 'no check          2,007 ms   20/20', 'ensureActive()      302 ms    3/20', 'catch Exception     253 ms   20/20', 'rethrow             251 ms    2/20']), 1, { w: 12.4, dy: .55 });
      lbl(S, 'l1', 19.0, 3.4, ['계산만 하는 반복은 250ms에 취소해도 2,007ms까지 20번을 다 돌았어요', 'a computation-only loop cancelled at 250 ms still ran all 20 steps until 2,007 ms'], 'r', 1, { w: 12.4 });
      lbl(S, 'l2', 19.0, 4.8, ['ensureActive()를 넣자 302ms, 3번째에서 멈췄어요', 'with ensureActive() it stopped at 302 ms after 3 steps'], 'g', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 6.2, ['CancellationException을 삼키자 남은 반복이 모두 실행됐어요', 'swallowing CancellationException ran every remaining step'], 'w', 3, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['취소는 협력이에요, 확인하고 예외는 다시 던져요', 'cancellation is cooperative: check for it and rethrow'], 'a', 4, { w: 16.0 });
    },
    notes: [['코루틴의 cancel()은 멈추라는 요청일 뿐, 실행 중인 코드를 강제로 끊지 않아요 · 100ms씩 CPU를 쓰는 단계 20개짜리 작업을 250ms에 취소하고 언제 끝나는지 쟀어요', 'cancel() on a coroutine is only a request to stop and never forcibly interrupts running code, so a job of 20 steps each spinning the CPU for 100 ms was cancelled at 250 ms to see when it ended'], ['멈출 지점이 없는 반복은 2,007ms까지 20단계를 모두 실행했어요 · 취소 요청은 받았지만 확인하는 코드가 없었어요', 'with no point to stop at, the loop ran all 20 steps until 2,007 ms, having received the request but containing no code that checked it'], ['단계마다 ensureActive()를 부르자 302ms에 멈췄어요 · 3단계를 마친 뒤였어요 · delay나 yield 같은 suspend 함수도 이 확인을 해 줘요', 'calling ensureActive() each step stopped it at 302 ms after three steps, and suspend functions such as delay and yield perform the same check'], ['delay를 try/catch(e: Exception)로 감싸자 253ms에 끝났지만 20단계가 모두 실행됐어요 · 취소로 던져진 CancellationException을 삼켜 반복이 계속됐어요 · runCatching도 같았어요 · 다시 던지자 2단계에서 멈췄어요', 'wrapping delay in try/catch(e: Exception) ended at 253 ms but ran all 20 steps, the CancellationException thrown by cancellation being swallowed so the loop carried on, the same with runCatching, while rethrowing it stopped after 2 steps']],
    fin: [['취소는 요청일 뿐', 'cancellation is only a request', 'kox-xs kox-a'], ['확인하는 지점이 필요해요', 'it needs checkpoints'], ['CancellationException은 다시 던져요', 'rethrow CancellationException']],
    caps: [['취소 요청', 'A cancellation request'], ['확인 없는 반복', 'A loop with no check'], ['ensureActive', 'ensureActive'], ['삼켜진 취소', 'A swallowed cancellation'], ['협력적 취소', 'Cooperative cancellation']]
  });
}

