      lbl(S, 'l1', 19.0, 2.9, ['B가 실패하자 A와 C가 취소되고 범위가 113ms에 예외를 던졌어요', 'when B failed, A and C were cancelled and the scope threw at 113 ms'], 'r', 1, { w: 12.4 });
      lbl(S, 'l2', 19.0, 4.3, ['supervisorScope에서는 A와 C가 1,002~1,003ms에 끝까지 돌았어요', 'under supervisorScope, A and C ran to the end at 1,002 to 1,003 ms'], 'g', 2, { w: 12.4 });
