function sPlatT() {
  return CW('kt-platform', {
    code: ['// Java: static String findName(int id)', 'val a = Repo.findName(2)    // String!', 'a.length            // NPE, far from here', 'val b: String = Repo.findName(2)  // NPE', 'val c: String? = Repo.findName(2)  // ok'],
    hl: [[1, 2, 'danger'], [3, 1, 'warn'], [4, 1, 'ok'], null],
    draw: (S) => {
      mono(S, 'm0', 19.0, .5, nbs(['Cannot invoke "String.length()"', 'because "a" is null']), 1, { w: 12.4, dy: .55, c: 'kox-r' });
      lbl(S, 'l1', 19.0, 1.8, ['타입을 적지 않자 null이 그대로 들어와 쓰는 곳에서 터졌어요', 'with no declared type the null came in and blew up where it was used'], 'r', 1, { w: 12.4 });
      mono(S, 'm2', 19.0, 3.2, nbs(['findName(...) must not be null']), 2, { w: 12.4, c: 'kox-w' });
      lbl(S, 'l2', 19.0, 3.85, ['String으로 받자 대입하는 줄에서 바로 멈추고 어느 호출인지 알려 줬어요', 'declared as String, it stopped on the assignment and named the call'], 'w', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 5.3, ['String?로 받으면 컴파일러가 null 처리를 요구해요', 'declared as String?, the compiler demands null handling'], 'g', 3, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['Java에서 온 값은 타입을 직접 적어 경계를 정해요', 'declare the type of values from Java to fix the boundary'], 'a', 4, { w: 16.0 });
    },
    notes: [['Java 메서드는 null을 돌려줄 수 있는지 타입에 적혀 있지 않아요 · 그래서 Kotlin은 Java가 돌려준 String을 String!라는 플랫폼 타입으로 받아요 · null 검사를 하지 않아도 되고, 해도 돼요', 'a Java method\'s type does not say whether it may return null, so Kotlin receives a String from Java as the platform type String!, on which null checks are neither required nor forbidden'], ['null을 돌려주는 findName(2)를 타입 없이 a에 담았어요 · 담는 순간에는 아무 일도 없었어요 · a.length에서 NullPointerException: Cannot invoke "String.length()" because "a" is null이 났어요', 'findName(2), which returns null, was stored in a without a type, and nothing happened on assignment, the NullPointerException Cannot invoke "String.length()" because "a" is null coming only at a.length'], ['val b: String으로 받자 대입하는 줄에서 NullPointerException: findName(...) must not be null이 났어요 · 컴파일러가 경계에 검사를 넣어 어느 호출이 null을 줬는지 알려 줘요', 'declaring val b: String raised NullPointerException: findName(...) must not be null on the assignment line, the compiler inserting a check at the boundary that names the call that returned null'], ['val c: String?로 받으면 컴파일러가 c?.length처럼 null을 다루게 해요 · 실행하자 c?.length는 null이었어요 · Java 메서드에 @Nullable을 붙이자 a.length가 컴파일 오류가 됐어요', 'declaring val c: String? makes the compiler require null handling such as c?.length, which evaluated to null, and once the Java method was annotated @Nullable, a.length became a compile error']],
    fin: [['Java 값은 플랫폼 타입', 'Java values are platform types', 'kox-xs kox-a'], ['null은 멀리서 터져요', 'nulls blow up far away'], ['타입을 적어 경계를', 'declare a type at the boundary']],
    caps: [['플랫폼 타입', 'Platform types'], ['멀리서 터진 null', 'A null far away'], ['경계의 검사', 'A check at the boundary'], ['String?로 받기', 'Taking String?'], ['Java에서 온 값', 'Values from Java']]
  });
}

